import socket,time,sys,re,os
SOCK='/tmp/alpine-serial.sock'
class Serial:
    def __init__(self):
        self.s=socket.socket(socket.AF_UNIX,socket.SOCK_STREAM)
        self.s.settimeout(0.5)
        self.s.connect(SOCK)
        self.buf=b''
    def read(self, timeout=1.0):
        end=time.time()+timeout
        data=b''
        while time.time()<end:
            try:
                b=self.s.recv(65536)
                if not b: break
                data+=b
                end=time.time()+0.3
            except socket.timeout:
                pass
        self.buf+=data
        try:
            sys.stdout.buffer.write(data); sys.stdout.buffer.flush()
        except Exception: pass
        return data
    def send(self, text):
        if isinstance(text,str): text=text.encode()
        self.s.sendall(text)
    def wait(self, needle, timeout=300):
        if isinstance(needle,str): needle=needle.encode()
        end=time.time()+timeout
        data=b''
        while time.time()<end:
            if needle in self.buf:
                return True
            try:
                b=self.s.recv(65536)
                if not b: break
                self.buf+=b; data+=b
                try:
                    sys.stdout.buffer.write(b); sys.stdout.buffer.flush()
                except Exception: pass
            except socket.timeout:
                pass
        return False
    def clear(self): self.buf=b''
    def cmd(self, command, marker, timeout=300):
        self.clear()
        self.send(command+'\n')
        ok=self.wait(marker, timeout)
        return ok

def main():
    t=Serial()
    print('--- connected ---')
    t.send('\n')
    time.sleep(1)
    t.read(2)
    print('\n--- buffer ---\n', t.buf.decode('utf-8','replace')[-3000:])
if __name__=='__main__':
    main()
PY
